<script setup>
import { computed, onMounted, ref } from 'vue';
import { authService } from '../services';
import { createLogger, logException } from '../utils/logger';
import { previewKycFile, validateKycFile } from '../utils/kyc';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Tag from 'primevue/tag';
import Dialog from 'primevue/dialog';

const logger = createLogger('VerificationView');
const loading = ref(false); const statusLoading = ref(true); const historyLoading = ref(true); const detailsLoading = ref(false); const detailsVisible = ref(false); const enlargedVisible = ref(false); const progress = ref(0); const message = ref(''); const status = ref(null); const rejectionReason = ref(''); const submittedAt = ref(null); const step = ref(1); const isEditing = ref(false); const history = ref([]); const selectedDetails = ref(null); const enlargedDocument = ref(null);
const form = ref({ name: '', national_code: '', national_card_serial: '', home_phone: '', postal_address: '', iban: '', ownership_confirmed: false });
const files = ref({ residence_document: null, job_document: null, national_card_front: null, national_card_back: null, birth_certificate_p1: null, birth_certificate_p2: null });
const previews = ref({});
const fileLabels = { national_card_front: 'کارت ملی (روی کارت)', national_card_back: 'کارت ملی (پشت کارت)', birth_certificate_p1: 'شناسنامه (صفحه اول)', birth_certificate_p2: 'شناسنامه (صفحه دوم)', residence_document: 'مدرک سکونت', job_document: 'مدرک شغلی' };
const fileFields = Object.keys(fileLabels);
const isLocked = computed(() => status.value === 'pending' || status.value === 'approved');
const statusTitle = computed(() => ({ pending: 'مدارک شما با موفقیت ارسال شد و در صف بررسی اپراتور قرار دارد', approved: 'هویت شما تایید شده است', rejected: 'پرونده احراز هویت نیاز به اصلاح دارد' }[status.value]));
const statusClass = computed(() => `verification-status verification-status--${status.value}`);
const latestRejected = computed(() => history.value[0]?.status === 'rejected');
function selectFile(field, event) { const file = event.target.files?.[0]; if (!file) return; const error = validateKycFile(file); if (error) { message.value = error; event.target.value = ''; return; } if (previews.value[field]) URL.revokeObjectURL(previews.value[field]); files.value[field] = file; previews.value[field] = previewKycFile(file); message.value = ''; }
function removeFile(field) { if (previews.value[field]) URL.revokeObjectURL(previews.value[field]); files.value[field] = null; previews.value[field] = null; }
function canContinue() { if (step.value === 1) return form.value.name.trim().length >= 2 && /^\d{10}$/.test(form.value.national_code) && form.value.national_card_serial.trim().length > 0; if (step.value === 2) return /^0[1-9]\d{9}$/.test(form.value.home_phone) && form.value.postal_address.trim().length >= 10 && Boolean(files.value.residence_document); if (step.value === 3) return /^IR\d{24}$/i.test(form.value.iban) && Boolean(files.value.job_document); if (step.value === 4) return fileFields.slice(0, 4).every((field) => Boolean(files.value[field])); return form.value.ownership_confirmed; }
function stepError() { if (step.value === 1) return 'نام، کد ملی ۱۰ رقمی و شماره سریال کارت ملی را کامل کنید.'; if (step.value === 2) return 'تلفن ثابت ۱۱ رقمی، آدرس کامل و مدرک سکونت الزامی است.'; if (step.value === 3) return 'شماره شبای معتبر و مدرک شغلی را وارد کنید.'; if (step.value === 4) return 'هر چهار تصویر هویتی را بارگذاری کنید.'; return 'برای ارسال پرونده، تعهدنامه را تایید کنید.'; }
function next() { if (canContinue() && step.value < 5) { step.value += 1; message.value = ''; } else message.value = stepError(); }
function previous() { step.value = Math.max(1, step.value - 1); message.value = ''; }
async function loadStatus() { statusLoading.value = true; try { const response = await authService.getKycStatus(); const data = response.data || response.verification; status.value = response.status || (data ? data.status : 'not_submitted'); rejectionReason.value = data?.rejection_reason || ''; submittedAt.value = data?.submitted_at || null; if (data) Object.keys(form.value).forEach((field) => { if (data[field] !== undefined && data[field] !== null) form.value[field] = data[field]; }); } catch (exception) { logger.error('loadStatus', 'KYC status request failed', logException(exception)); } finally { statusLoading.value = false; } }
async function loadHistory() { historyLoading.value = true; try { const response = await authService.getKycHistory(); history.value = response.data || []; logger.info('renderHistory', 'KYC history rendered', { count: history.value.length, latestStatus: history.value[0]?.status || 'not_submitted' }); } catch (exception) { logger.error('loadHistory', 'KYC history request failed', logException(exception)); } finally { historyLoading.value = false; } }
async function openDetails(row) { detailsLoading.value = true; detailsVisible.value = true; try { const response = await authService.getKycDetails(row.id); const details = response.data; const documents = {}; for (const [type, url] of Object.entries(details.documents || {})) documents[type] = url ? await authService.getKycDocument(row.id, type) : null; selectedDetails.value = { ...details, documents }; } catch (exception) { selectedDetails.value = null; logger.error('openDetails', 'KYC details request failed', logException(exception)); } finally { detailsLoading.value = false; } }
async function submit() { if (!canContinue()) { message.value = stepError(); return; } loading.value = true; progress.value = 15; message.value = ''; const data = new FormData(); Object.entries(form.value).forEach(([key, value]) => data.append(key, key === 'ownership_confirmed' ? (value ? '1' : '0') : (value ? String(value) : ''))); fileFields.forEach((field) => { if (files.value[field]) data.append(field, files.value[field]); }); try { progress.value = 55; const response = await authService.submitKyc(data); progress.value = 100; status.value = response.status || 'pending'; isEditing.value = false; message.value = 'مدارک شما با موفقیت ارسال شد و در صف بررسی اپراتور قرار دارد.'; logger.info('submit', 'KYC verification submitted', { status: status.value }); } catch (exception) { logger.error('submit', 'KYC submission failed', logException(exception)); message.value = exception.response?.data?.message || 'ارسال مدارک انجام نشد.'; } finally { loading.value = false; } }
function resubmit() { if (!latestRejected.value) return; isEditing.value = true; message.value = ''; step.value = 1; }
function formatDate(value) { if (!value) return 'به‌تازگی'; return new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium' }).format(new Date(value)); }
function documentLabel(type) { return fileLabels[type] || 'مدرک'; }
function enlargeDocument(document) { enlargedDocument.value = document; enlargedVisible.value = true; }
onMounted(() => { loadStatus(); loadHistory(); });
</script>

<template>
<section class="module-view verification-view" dir="rtl">
    <div class="verification-container">
    <header class="module-header"><span class="module-kicker">امنیت حساب</span><h1>تایید هویت و مدارک</h1><p>برای استفاده کامل از امکانات، اطلاعات هویتی خود را ثبت کنید.</p></header>
    <div v-if="statusLoading" class="verification-loading" role="status"><i class="pi pi-spin pi-spinner"></i>در حال دریافت وضعیت پرونده...</div>
    <template v-else>
        <div v-if="status !== 'not_submitted'" :class="['verification-status', `verification-status--${status}`]">
            <i class="verification-status__icon" :class="status === 'approved' ? 'pi pi-check-circle' : status === 'rejected' ? 'pi pi-times-circle' : 'pi pi-clock'"></i>
            <div class="verification-status__copy"><strong>{{ status === 'pending' ? 'مدارک شما در صف بررسی اپراتور قرار دارد' : statusTitle }}</strong><p v-if="status === 'pending'">کارشناسان مستروام در حال تطبیق مدارک هویتی و بانکی شما هستند. نتیجه از طریق پیامک و همین صفحه اعلام خواهد شد.</p><p v-else-if="status === 'rejected'">{{ rejectionReason || 'لطفاً اطلاعات و مدارک را اصلاح و دوباره ارسال کنید.' }}</p><p v-else-if="status === 'approved'">دسترسی کامل حساب شما فعال است.</p></div>
            <span v-if="status === 'pending'" class="verification-status__date">تاریخ ارسال: {{ formatDate(submittedAt) }}</span><button v-if="status === 'rejected'" type="button" @click="resubmit">ویرایش و ارسال مجدد مدارک</button>
        </div>
        <section v-if="!historyLoading && history.length" class="verification-history">
            <header class="verification-history__header"><div><span class="module-kicker">سوابق پرونده</span><h2>تاریخچه درخواست‌های احراز هویت</h2></div><span class="verification-history__count">{{ history.length }} درخواست</span></header>
            <div class="verification-table-scroll"><DataTable :value="history" class="verification-table p-datatable-sm" striped-rows responsive-layout="scroll" data-key="id">
                <Column header="#" style="width: 70px"><template #body="slotProps">{{ slotProps.index + 1 }}</template></Column>
                <Column field="submitted_at" header="تاریخ ثبت" />
                <Column header="وضعیت"><template #body="slotProps"><span :title="slotProps.data.status === 'pending' ? 'پرونده در حال بررسی است و تا اعلام نتیجه نهایی امکان ویرایش وجود ندارد' : slotProps.data.status === 'approved' ? 'این پرونده تایید شده است و امکان ویرایش آن وجود ندارد' : ''"><Tag :value="slotProps.data.status === 'approved' ? 'تایید شده' : slotProps.data.status === 'rejected' ? 'رد شده' : 'در صف بررسی'" :severity="slotProps.data.status === 'approved' ? 'success' : slotProps.data.status === 'rejected' ? 'danger' : 'warn'"><template #icon><i :class="slotProps.data.status === 'approved' ? 'pi pi-check-circle' : slotProps.data.status === 'rejected' ? 'pi pi-times-circle' : 'pi pi-clock'"></i></template></Tag></span></template></Column>
                <Column header="علت رد"><template #body="slotProps"><span v-if="slotProps.data.rejection_reason" class="history-reason" :title="slotProps.data.rejection_reason">{{ slotProps.data.rejection_reason }}</span><span v-else class="history-empty">-</span></template></Column>
                <Column header="عملیات"><template #body="slotProps"><button v-if="slotProps.data.status === 'pending' || slotProps.data.status === 'approved'" type="button" class="history-action history-action--secondary" @click="openDetails(slotProps.data)"><i class="pi pi-eye"></i>مشاهده مدارک</button><button v-else-if="slotProps.index === 0 && latestRejected" type="button" class="history-action" @click="resubmit"><i class="pi pi-pencil"></i>اصلاح و ارسال مجدد</button></template></Column>
            </DataTable></div>
        </section>
        <form v-if="status === 'not_submitted' || isEditing" class="verification-form" @submit.prevent="submit">
            <fieldset class="verification-fieldset">
                <div class="verification-steps"><span v-for="index in 5" :key="index" :class="{ active: step === index, done: step > index }"><b>{{ index }}</b>{{ ['هویتی', 'سکونت', 'مالی', 'مدارک', 'تعهدنامه'][index - 1] }}</span></div>
                <p v-if="message" class="module-notice" role="alert">{{ message }}</p>
                <section v-if="step === 1" class="verification-grid"><label>نام و نام خانوادگی<input v-model.trim="form.name" required></label><label>کد ملی<input v-model.trim="form.national_code" inputmode="numeric" maxlength="10" required></label><label class="wide">شماره سریال پشت کارت ملی<input v-model.trim="form.national_card_serial" required></label></section>
                <section v-else-if="step === 2" class="verification-grid"><label>تلفن ثابت منزل<input v-model.trim="form.home_phone" inputmode="tel" maxlength="11" placeholder="02112345678" required></label><label class="wide">آدرس دقیق پستی<textarea v-model.trim="form.postal_address" rows="4" required></textarea></label><div class="upload-card wide"><strong>مدرک سکونت</strong><input type="file" accept="image/*,.pdf" @change="selectFile('residence_document', $event)"><small>سند یا اجاره‌نامه، حداکثر ۴ مگابایت</small></div></section>
                <section v-else-if="step === 3" class="verification-grid"><label class="wide">شماره شبا به نام متقاضی<input v-model.trim="form.iban" dir="ltr" placeholder="IR000000000000000000000000" required><small>شماره شبا باید به نام صاحب کد ملی باشد.</small></label><div class="upload-card wide"><strong>مدرک شغلی</strong><input type="file" accept="image/*,.pdf" @change="selectFile('job_document', $event)"><small>فیش حقوقی، جواز کسب یا گواهی اشتغال</small></div></section>
                <section v-else-if="step === 4" class="document-grid"><div v-for="field in fileFields.slice(0, 4)" :key="field" class="document-card"><div v-if="previews[field]" class="document-preview"><img :src="previews[field]" :alt="fileLabels[field]"><button type="button" aria-label="حذف فایل" @click="removeFile(field)"><i class="pi pi-times"></i></button></div><i v-else class="pi pi-id-card"></i><strong>{{ fileLabels[field] }}</strong><input type="file" accept="image/*,.pdf" @change="selectFile(field, $event)"><small>{{ files[field]?.name || 'انتخاب فایل، حداکثر ۴ مگابایت' }}</small></div></section>
                <section v-else class="commitment-card"><i class="pi pi-shield"></i><label><input v-model="form.ownership_confirmed" type="checkbox"> تایید می‌کنم که شماره موبایل و حساب بانکی معرفی‌شده منحصراً به نام اینجانب و صاحب کد ملی فوق می‌باشد.</label></section>
            </fieldset>
            <footer class="verification-actions"><button v-if="step > 1" type="button" class="secondary-action" @click="previous">قبلی</button><button v-if="step < 5" type="button" class="primary-action" @click="next">ادامه</button><button v-else type="submit" class="primary-action" :disabled="loading">{{ loading ? 'در حال ارسال...' : 'ارسال برای بررسی' }}</button></footer><div v-if="loading" class="upload-progress"><span :style="{ width: `${progress}%` }"></span></div>
        </form>
        <Dialog v-model:visible="detailsVisible" modal="true" dismissable-mask :draggable="false" :header="selectedDetails ? `جزئیات مدارک ارسالی (درخواست #${selectedDetails.id})` : 'جزئیات مدارک ارسالی'" :style="{ width: '90vw', maxWidth: '650px' }" :pt="{ root: { class: 'kyc-details-dialog__root' }, mask: { class: 'kyc-dialog-mask' }, header: { class: 'kyc-details-dialog__header' }, content: { class: 'kyc-details-dialog__content' }, footer: { class: 'kyc-details-dialog__footer' } }" class="kyc-details-dialog" dir="rtl">
            <div v-if="detailsLoading" class="details-loading"><i class="pi pi-spin pi-spinner"></i>در حال دریافت جزئیات...</div>
            <div v-else-if="selectedDetails" class="kyc-details-content">
                <header class="details-header"><div><strong>درخواست #{{ selectedDetails.id }}</strong><span>تاریخ ارسال: {{ selectedDetails.submitted_at }}</span></div><Tag :value="selectedDetails.status === 'approved' ? 'تایید شده' : 'در صف بررسی'" :severity="selectedDetails.status === 'approved' ? 'success' : 'warn'" /></header>
                <section class="details-fields"><div><small>کد ملی</small><strong>{{ selectedDetails.national_code }}</strong></div><div><small>تلفن ثابت</small><strong>{{ selectedDetails.home_phone }}</strong></div><div class="details-fields__wide"><small>آدرس</small><strong>{{ selectedDetails.postal_address }}</strong></div><div><small>شماره شبا</small><strong dir="ltr">{{ selectedDetails.iban }}</strong></div></section>
                <section class="details-documents"><h3>مدارک ارسال‌شده</h3><div class="details-gallery"><template v-for="(url, type) in selectedDetails.documents" :key="type"><button v-if="url" type="button" class="details-thumbnail" @click="enlargeDocument({ url, label: documentLabel(type) })"><img :src="url" :alt="documentLabel(type)"><span>{{ documentLabel(type) }}</span></button></template></div></section>
            </div>
            <template #footer><button type="button" class="details-close" @click="detailsVisible = false">بستن</button></template>
        </Dialog>
        <Dialog v-model:visible="enlargedVisible" modal="true" dismissable-mask :draggable="false" :header="enlargedDocument?.label || 'نمایش مدرک'" :pt="{ root: { class: 'kyc-image-dialog__root' }, mask: { class: 'kyc-dialog-mask' } }" class="kyc-image-dialog"><img v-if="enlargedDocument" class="enlarged-document" :src="enlargedDocument.url" :alt="enlargedDocument.label"></Dialog>
    </template>
    </div>
</section>
</template>

<style scoped>
